contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    receive() external payable {}

    function run(uint amount, address probe) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (amount)); require(amount <= 1000000000000000000000000000000);
        require(amount > 0, "amount must be positive");
        require(address(this).balance >= amount, "insufficient test balance");

        c.addToBalance{value: amount}(); if (__ESBMC_reverted()) return;
        uint selfBal = c.getBalance(address(this)); if (__ESBMC_reverted()) return;
        uint probeBal = c.getBalance(probe); if (__ESBMC_reverted()) return;

        assert(selfBal == amount && (probe == address(this) ? probeBal == selfBal : probeBal == 0));
    }
}

