// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {Reentrance} from "../src/Reentrance.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    Reentrance c;

    function setUp() public {
        c = new Reentrance();
    }

    function _run(uint256 amount, address probe) internal {
        amount = bound(amount, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(amount > 0);
        vm.assume(address(this).balance >= amount);
        try c.addToBalance{value: amount}() {} catch { return; }
        uint256 selfBal;
        try c.getBalance(address(this)) returns (uint256 __r) { selfBal = __r; } catch { return; }
        uint256 probeBal;
        try c.getBalance(probe) returns (uint256 __r) { probeBal = __r; } catch { return; }
        assertTrue(selfBal == amount && (probe == address(this) ? probeBal == selfBal : probeBal == 0));
    }

    function testFuzz_run(uint256 amount, address probe) public {
        vm.assume(probe.code.length == 0 && uint160(probe) > 0xffff && probe != address(this) && probe != address(c) && probe != 0x7109709ECfa91a80626fF3989D68f67F5b1DD12D && probe != 0x000000000000000000636F6e736F6c652e6c6f67 && probe != 0x4e59b44847b379578588920cA78FbF26c0B4956C && probe != 0x1804c8AB1F12E6bbf3894d4083f33e07309d1f38);
        _run(amount, probe);
    }

    receive() external payable {}
}
